/**
 * Eclispe Calculator
 * Generated by SHAFF
 * Modern Scientific Calculator with Safe AST/Pratt Tokenizer & Parser,
 * 3-Way Theme Switcher (Light/Dark/System), Calculation History, and responsive UI.
 */

(function () {
  'use strict';

  // =========================================================================
  // STATE MANAGEMENT
  // =========================================================================
  const state = {
    expression: '',       // Internal expression string
    angleUnit: 'DEG',     // 'DEG' or 'RAD'
    isSecondActive: false,// 2nd function toggle for inverse trig
    theme: 'light',       // 'light', 'dark', or 'system'
    isCalculated: false,  // True right after an '=' calculation
    lastResult: null,     // Stored last numeric result
    history: []           // Array of { expression, result, timestamp }
  };

  // Unicode Character Constants
  const SYM = {
    PI: '\u03C0',
    SQRT: '\u221A',
    SQUARE: '\u00B2',
    MULT: '\u00D7',
    DIV: '\u00F7',
    SUB: '\u2212',
    DEL: '\u232B',
    PLUSMINUS: '\u00B1'
  };

  // =========================================================================
  // DOM ELEMENTS
  // =========================================================================
  const exprDisplay = document.getElementById('expressionLine');
  const resultDisplay = document.getElementById('resultLine');
  const statusMsg = document.getElementById('statusMessage');
  const angleUnitBtn = document.getElementById('angleUnitBtn');
  const btnAngleKey = document.getElementById('btnAngleKey');
  const btnSecond = document.getElementById('btnSecond');
  const themeToggleBtn = document.getElementById('themeToggleBtn');
  const themeLabel = document.getElementById('themeLabel');
  const keypadLayout = document.getElementById('keypadLayout');
  const tabButtons = document.querySelectorAll('.tab-button');
  const trigButtons = document.querySelectorAll('.trig-btn');

  // History DOM Elements
  const historyToggleBtn = document.getElementById('historyToggleBtn');
  const historyDrawer = document.getElementById('historyDrawer');
  const closeHistoryBtn = document.getElementById('closeHistoryBtn');
  const clearHistoryBtn = document.getElementById('clearHistoryBtn');
  const historyList = document.getElementById('historyList');
  const historyCountBadge = document.getElementById('historyCountBadge');

  // =========================================================================
  // THEME MANAGEMENT (3 Modes: Light, Dark, System)
  // =========================================================================
  const THEMES = ['light', 'dark', 'system'];
  const STORAGE_KEY = 'eclipse_calculator_theme';
  const STORAGE_KEY_HISTORY = 'eclipse_calculator_history';

  function getSystemPreference() {
    return window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
  }

  function applyTheme(mode) {
    state.theme = mode;
    try {
      localStorage.setItem(STORAGE_KEY, mode);
    } catch {
      // Ignore if localStorage unavailable
    }
    document.body.setAttribute('data-theme-setting', mode);

    const effectiveTheme = mode === 'system' ? getSystemPreference() : mode;
    document.body.setAttribute('data-theme', effectiveTheme);

    if (themeLabel) {
      themeLabel.textContent = mode;
    }
  }

  function cycleTheme() {
    const currentIndex = THEMES.indexOf(state.theme);
    const nextTheme = THEMES[(currentIndex + 1) % THEMES.length];
    applyTheme(nextTheme);
  }

  function initTheme() {
    let saved = null;
    try {
      saved = localStorage.getItem(STORAGE_KEY);
    } catch {}

    if (saved && THEMES.includes(saved)) {
      applyTheme(saved);
    } else {
      applyTheme('light');
    }

    if (window.matchMedia) {
      const systemMedia = window.matchMedia('(prefers-color-scheme: dark)');
      systemMedia.addEventListener('change', () => {
        if (state.theme === 'system') {
          applyTheme('system');
        }
      });
    }

    if (themeToggleBtn) {
      themeToggleBtn.addEventListener('click', cycleTheme);
    }
  }

  // =========================================================================
  // CALCULATION HISTORY
  // =========================================================================

  function saveHistory() {
    try {
      localStorage.setItem(STORAGE_KEY_HISTORY, JSON.stringify(state.history));
    } catch {}
  }

  function loadHistory() {
    try {
      const saved = localStorage.getItem(STORAGE_KEY_HISTORY);
      if (saved) {
        state.history = JSON.parse(saved);
      }
    } catch {
      state.history = [];
    }
    renderHistory();
  }

  function renderHistory() {
    if (historyCountBadge) {
      historyCountBadge.textContent = state.history.length;
    }

    if (!historyList) return;

    if (state.history.length === 0) {
      historyList.innerHTML = '<div class="history-empty">No calculations yet</div>';
      return;
    }

    historyList.innerHTML = '';
    state.history.forEach((item, index) => {
      const el = document.createElement('div');
      el.className = 'history-item';
      el.setAttribute('role', 'button');
      el.setAttribute('tabindex', '0');
      el.setAttribute('title', 'Click to recall this result');

      el.innerHTML = `
        <div class="history-item-expr">${escapeHtml(item.expression)} =</div>
        <div class="history-item-res">${escapeHtml(item.result)}</div>
      `;

      el.addEventListener('click', () => {
        recallHistoryItem(item);
      });

      el.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          recallHistoryItem(item);
        }
      });

      historyList.appendChild(el);
    });
  }

  function escapeHtml(str) {
    if (!str) return '';
    return str
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  function addHistory(expression, result) {
    if (!expression || !result) return;
    // Don't duplicate consecutive identical operations
    if (state.history.length > 0 && state.history[0].expression === expression && state.history[0].result === result) {
      return;
    }

    state.history.unshift({
      expression,
      result,
      timestamp: Date.now()
    });

    // Limit to latest 50 history entries
    if (state.history.length > 50) {
      state.history.pop();
    }

    saveHistory();
    renderHistory();
  }

  function clearHistory() {
    state.history = [];
    saveHistory();
    renderHistory();
    setStatus('HISTORY CLEARED');
  }

  function toggleHistoryDrawer(forceOpen) {
    if (!historyDrawer) return;
    const shouldOpen = typeof forceOpen === 'boolean'
      ? forceOpen
      : !historyDrawer.classList.contains('open');

    if (shouldOpen) {
      historyDrawer.classList.add('open');
      historyDrawer.setAttribute('aria-hidden', 'false');
    } else {
      historyDrawer.classList.remove('open');
      historyDrawer.setAttribute('aria-hidden', 'true');
    }
  }

  function recallHistoryItem(item) {
    state.expression = item.result.toString();
    state.lastResult = parseFloat(item.result) || null;
    state.isCalculated = true;
    updateDisplays();
    if (resultDisplay) resultDisplay.textContent = item.result;
    setStatus('RECALLED');
    toggleHistoryDrawer(false);
  }

  function initHistory() {
    loadHistory();

    if (historyToggleBtn) {
      historyToggleBtn.addEventListener('click', () => toggleHistoryDrawer());
    }

    if (closeHistoryBtn) {
      closeHistoryBtn.addEventListener('click', () => toggleHistoryDrawer(false));
    }

    if (clearHistoryBtn) {
      clearHistoryBtn.addEventListener('click', clearHistory);
    }
  }

  // =========================================================================
  // DEG / RAD & 2ND FUNCTION TOGGLES
  // =========================================================================
  function setAngleUnit(unit) {
    state.angleUnit = unit;
    if (angleUnitBtn) {
      const degSpan = angleUnitBtn.querySelector('.unit-deg');
      const radSpan = angleUnitBtn.querySelector('.unit-rad');
      if (degSpan && radSpan) {
        if (unit === 'DEG') {
          degSpan.classList.add('active');
          radSpan.classList.remove('active');
        } else {
          degSpan.classList.remove('active');
          radSpan.classList.add('active');
        }
      }
    }

    if (btnAngleKey) {
      if (unit === 'DEG') {
        btnAngleKey.textContent = 'Rad';
        btnAngleKey.title = 'Switch to Radians';
      } else {
        btnAngleKey.textContent = 'Deg';
        btnAngleKey.title = 'Switch to Degrees';
      }
    }
    updateLivePreview();
  }

  function toggleAngleUnit() {
    setAngleUnit(state.angleUnit === 'DEG' ? 'RAD' : 'DEG');
  }

  function toggleSecondFunction() {
    state.isSecondActive = !state.isSecondActive;
    if (btnSecond) {
      btnSecond.classList.toggle('active', state.isSecondActive);
    }

    trigButtons.forEach(btn => {
      const normalFunc = btn.getAttribute('data-func');
      const invFunc = btn.getAttribute('data-inv');
      if (state.isSecondActive && invFunc) {
        btn.textContent = invFunc;
        btn.title = `Inverse ${normalFunc} (${invFunc})`;
      } else {
        btn.textContent = normalFunc;
        btn.title = normalFunc.toUpperCase();
      }
    });
  }

  // =========================================================================
  // SAFE MATHEMATICAL TOKENIZER & PARSER (NO eval())
  // =========================================================================

  const TokenType = {
    NUMBER: 'NUMBER',
    OPERATOR: 'OPERATOR',
    FUNCTION: 'FUNCTION',
    LPAREN: 'LPAREN',
    RPAREN: 'RPAREN',
    POSTFIX: 'POSTFIX'
  };

  function factorial(n) {
    if (n < 0) throw new Error('Invalid factorial operand');
    if (!Number.isInteger(n)) throw new Error('Factorial requires integer');
    if (n > 170) return Infinity;
    let res = 1;
    for (let i = 2; i <= n; i++) res *= i;
    return res;
  }

  function cleanFloat(val) {
    if (typeof val !== 'number' || isNaN(val)) return val;
    if (!isFinite(val)) return val;
    if (Math.abs(val) < 1e-14) return 0;
    const precision = 12;
    return parseFloat(val.toPrecision(precision));
  }

  function tokenize(str) {
    const tokens = [];
    let i = 0;

    let cleanStr = str
      .replace(/\u00D7/g, '*')
      .replace(/\u00F7/g, '/')
      .replace(/\u2212/g, '-')
      .replace(/\u221A/g, 'sqrt')
      .replace(/\u03C0/g, 'PI')
      .replace(/\s+/g, '');

    const len = cleanStr.length;
    const isDigit = c => (c >= '0' && c <= '9') || c === '.';
    const isAlpha = c => (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');

    while (i < len) {
      const ch = cleanStr[i];

      if (isDigit(ch)) {
        let numStr = '';
        let hasDot = false;
        while (i < len && isDigit(cleanStr[i])) {
          if (cleanStr[i] === '.') {
            if (hasDot) break;
            hasDot = true;
          }
          numStr += cleanStr[i];
          i++;
        }
        tokens.push({ type: TokenType.NUMBER, value: parseFloat(numStr) });
        continue;
      }

      if (ch === '(') {
        tokens.push({ type: TokenType.LPAREN, value: '(' });
        i++;
        continue;
      }
      if (ch === ')') {
        tokens.push({ type: TokenType.RPAREN, value: ')' });
        i++;
        continue;
      }

      if (ch === '+' || ch === '-' || ch === '*' || ch === '/' || ch === '^' || ch === '%') {
        tokens.push({ type: TokenType.OPERATOR, value: ch });
        i++;
        continue;
      }

      if (ch === '!') {
        tokens.push({ type: TokenType.POSTFIX, value: '!' });
        i++;
        continue;
      }
      if (ch === '\u00B2' || ch === '²') {
        tokens.push({ type: TokenType.POSTFIX, value: '²' });
        i++;
        continue;
      }

      if (isAlpha(ch)) {
        let name = '';
        while (i < len && isAlpha(cleanStr[i])) {
          name += cleanStr[i];
          i++;
        }

        const lower = name.toLowerCase();
        if (lower === 'pi') {
          tokens.push({ type: TokenType.NUMBER, value: Math.PI });
        } else if (lower === 'e') {
          tokens.push({ type: TokenType.NUMBER, value: Math.E });
        } else if (['sin', 'cos', 'tan', 'asin', 'acos', 'atan', 'log', 'ln', 'sqrt', 'abs'].includes(lower)) {
          tokens.push({ type: TokenType.FUNCTION, value: lower });
        } else {
          throw new Error('Unknown symbol: ' + name);
        }
        continue;
      }

      throw new Error('Invalid character: ' + ch);
    }

    // Insert implicit multiplications
    const implicitTokens = [];
    for (let k = 0; k < tokens.length; k++) {
      const current = tokens[k];
      implicitTokens.push(current);

      if (k < tokens.length - 1) {
        const next = tokens[k + 1];
        const currentIsOperand = current.type === TokenType.NUMBER || current.type === TokenType.RPAREN || current.type === TokenType.POSTFIX;
        const nextIsOperand = next.type === TokenType.NUMBER || next.type === TokenType.LPAREN || next.type === TokenType.FUNCTION;

        if (currentIsOperand && nextIsOperand) {
          implicitTokens.push({ type: TokenType.OPERATOR, value: '*' });
        }
      }
    }

    return implicitTokens;
  }

  function evaluateTokens(tokens, angleUnit) {
    const outputQueue = [];
    const opStack = [];

    const precedence = {
      '+': 1,
      '-': 1,
      '*': 2,
      '/': 2,
      '%': 2,
      'u-': 3,
      'u+': 3,
      '^': 4
    };

    const isRightAssociative = op => op === '^' || op === 'u-' || op === 'u+';

    for (let i = 0; i < tokens.length; i++) {
      const token = tokens[i];

      if (token.type === TokenType.NUMBER) {
        outputQueue.push(token);
      } else if (token.type === TokenType.FUNCTION) {
        opStack.push(token);
      } else if (token.type === TokenType.POSTFIX) {
        outputQueue.push(token);
      } else if (token.type === TokenType.OPERATOR) {
        let op = token.value;
        const prev = tokens[i - 1];
        const isUnary = !prev || prev.type === TokenType.OPERATOR || prev.type === TokenType.LPAREN || prev.type === TokenType.FUNCTION;

        if (isUnary) {
          if (op === '-') op = 'u-';
          else if (op === '+') op = 'u+';
          else throw new Error('Syntax error before ' + op);
        }

        const opToken = { ...token, value: op };

        while (opStack.length > 0) {
          const top = opStack[opStack.length - 1];
          if (top.type === TokenType.OPERATOR) {
            const pCurrent = precedence[op];
            const pTop = precedence[top.value];
            if ((!isRightAssociative(op) && pCurrent <= pTop) || (isRightAssociative(op) && pCurrent < pTop)) {
              outputQueue.push(opStack.pop());
              continue;
            }
          }
          break;
        }
        opStack.push(opToken);
      } else if (token.type === TokenType.LPAREN) {
        opStack.push(token);
      } else if (token.type === TokenType.RPAREN) {
        let foundLparen = false;
        while (opStack.length > 0) {
          const top = opStack.pop();
          if (top.type === TokenType.LPAREN) {
            foundLparen = true;
            break;
          }
          outputQueue.push(top);
        }
        if (!foundLparen) throw new Error('Mismatched parentheses');

        if (opStack.length > 0 && opStack[opStack.length - 1].type === TokenType.FUNCTION) {
          outputQueue.push(opStack.pop());
        }
      }
    }

    while (opStack.length > 0) {
      const top = opStack.pop();
      if (top.type === TokenType.LPAREN || top.type === TokenType.RPAREN) {
        throw new Error('Mismatched parentheses');
      }
      outputQueue.push(top);
    }

    const valStack = [];
    const toRad = deg => (deg * Math.PI) / 180;
    const toDeg = rad => (rad * 180) / Math.PI;

    for (const item of outputQueue) {
      if (item.type === TokenType.NUMBER) {
        valStack.push(item.value);
      } else if (item.type === TokenType.POSTFIX) {
        if (valStack.length < 1) throw new Error('Missing operand for ' + item.value);
        const a = valStack.pop();
        if (item.value === '!') {
          valStack.push(factorial(a));
        } else if (item.value === '²' || item.value === '\u00B2') {
          valStack.push(a * a);
        }
      } else if (item.type === TokenType.FUNCTION) {
        if (valStack.length < 1) throw new Error('Missing argument for ' + item.value);
        const a = valStack.pop();
        let res;

        switch (item.value) {
          case 'sin': {
            const rad = angleUnit === 'DEG' ? toRad(a) : a;
            res = Math.sin(rad);
            break;
          }
          case 'cos': {
            const rad = angleUnit === 'DEG' ? toRad(a) : a;
            res = Math.cos(rad);
            break;
          }
          case 'tan': {
            const rad = angleUnit === 'DEG' ? toRad(a) : a;
            if (cleanFloat(Math.cos(rad)) === 0) {
              throw new Error('Undefined (tan asymptote)');
            }
            res = Math.tan(rad);
            break;
          }
          case 'asin': {
            if (a < -1 || a > 1) throw new Error('Invalid asin domain [-1, 1]');
            const rad = Math.asin(a);
            res = angleUnit === 'DEG' ? toDeg(rad) : rad;
            break;
          }
          case 'acos': {
            if (a < -1 || a > 1) throw new Error('Invalid acos domain [-1, 1]');
            const rad = Math.acos(a);
            res = angleUnit === 'DEG' ? toDeg(rad) : rad;
            break;
          }
          case 'atan': {
            const rad = Math.atan(a);
            res = angleUnit === 'DEG' ? toDeg(rad) : rad;
            break;
          }
          case 'log': {
            if (a <= 0) throw new Error('Invalid log domain (>0)');
            res = Math.log10(a);
            break;
          }
          case 'ln': {
            if (a <= 0) throw new Error('Invalid ln domain (>0)');
            res = Math.log(a);
            break;
          }
          case 'sqrt': {
            if (a < 0) throw new Error('Negative square root');
            res = Math.sqrt(a);
            break;
          }
          case 'abs': {
            res = Math.abs(a);
            break;
          }
          default:
            throw new Error('Unsupported function: ' + item.value);
        }
        valStack.push(cleanFloat(res));
      } else if (item.type === TokenType.OPERATOR) {
        if (item.value === 'u-') {
          if (valStack.length < 1) throw new Error('Missing operand');
          valStack.push(-valStack.pop());
        } else if (item.value === 'u+') {
          if (valStack.length < 1) throw new Error('Missing operand');
        } else {
          if (valStack.length < 2) throw new Error('Missing operand for ' + item.value);
          const b = valStack.pop();
          const a = valStack.pop();
          let r;

          switch (item.value) {
            case '+':
              r = a + b;
              break;
            case '-':
              r = a - b;
              break;
            case '*':
              r = a * b;
              break;
            case '/':
              if (b === 0) throw new Error('Cannot divide by zero');
              r = a / b;
              break;
            case '%':
              r = a % b;
              break;
            case '^':
              r = Math.pow(a, b);
              break;
            default:
              throw new Error('Unknown operator: ' + item.value);
          }
          valStack.push(cleanFloat(r));
        }
      }
    }

    if (valStack.length !== 1) {
      throw new Error('Invalid Expression');
    }

    return cleanFloat(valStack[0]);
  }

  function safeEvaluate(expressionStr, angleUnit) {
    if (!expressionStr || expressionStr.trim() === '') return 0;
    const tokens = tokenize(expressionStr);
    return evaluateTokens(tokens, angleUnit);
  }

  // =========================================================================
  // DISPLAY & UI CONTROLLER
  // =========================================================================

  function formatDisplayNumber(num) {
    if (typeof num !== 'number' || isNaN(num)) return num;
    if (!isFinite(num)) return num > 0 ? 'Infinity' : '-Infinity';
    if (Math.abs(num) >= 1e14 || (Math.abs(num) > 0 && Math.abs(num) < 1e-6)) {
      return num.toExponential(8).replace(/\.?0+e/, 'e');
    }
    return num.toString();
  }

  function updateDisplays() {
    if (exprDisplay) exprDisplay.textContent = state.expression;

    if (resultDisplay) {
      const textLen = (resultDisplay.textContent || '').length;
      if (textLen > 12) {
        resultDisplay.classList.add('small-font');
      } else {
        resultDisplay.classList.remove('small-font');
      }
    }
  }

  function setStatus(msg, isError = false) {
    if (!statusMsg) return;
    statusMsg.textContent = msg;
    statusMsg.classList.toggle('error', isError);
  }

  function updateLivePreview() {
    if (!state.expression) {
      if (resultDisplay) resultDisplay.textContent = '0';
      setStatus('READY');
      return;
    }

    let previewExpr = state.expression;
    let openCount = 0;
    for (const c of previewExpr) {
      if (c === '(') openCount++;
      else if (c === ')') openCount--;
    }
    while (openCount > 0) {
      previewExpr += ')';
      openCount--;
    }

    try {
      const res = safeEvaluate(previewExpr, state.angleUnit);
      if (resultDisplay) resultDisplay.textContent = formatDisplayNumber(res);
      setStatus(state.angleUnit);
    } catch {
      setStatus(state.angleUnit);
    }
  }

  // =========================================================================
  // CALCULATOR ACTIONS
  // =========================================================================

  function clearAll() {
    state.expression = '';
    state.isCalculated = false;
    state.lastResult = null;
    if (exprDisplay) exprDisplay.textContent = '';
    if (resultDisplay) resultDisplay.textContent = '0';
    setStatus('CLEARED');
  }

  function backspace() {
    if (state.isCalculated) {
      clearAll();
      return;
    }

    if (!state.expression) return;

    const funcMatch = state.expression.match(/(asin|acos|atan|sin|cos|tan|log|ln|sqrt|abs)\($/);
    if (funcMatch) {
      state.expression = state.expression.slice(0, -funcMatch[0].length);
    } else if (state.expression.endsWith(SYM.SQRT + '(')) {
      state.expression = state.expression.slice(0, -2);
    } else {
      state.expression = state.expression.slice(0, -1);
    }

    updateDisplays();
    updateLivePreview();
  }

  function insertString(str) {
    const isNum = (str >= '0' && str <= '9') || str === '.' || str === SYM.PI || str === 'e';
    if (state.isCalculated) {
      if (isNum) {
        state.expression = '';
      }
      state.isCalculated = false;
    }

    state.expression += str;
    updateDisplays();
    updateLivePreview();
  }

  function insertOperator(op) {
    if (state.isCalculated) {
      state.isCalculated = false;
      if (state.lastResult !== null && !isNaN(state.lastResult)) {
        state.expression = state.lastResult.toString();
      }
    }

    if (op === '^2') {
      state.expression += SYM.SQUARE;
    } else {
      state.expression += op;
    }

    updateDisplays();
    updateLivePreview();
  }

  function insertFunction(funcName) {
    if (state.isCalculated) {
      state.isCalculated = false;
    }

    if (funcName === 'recip') {
      state.expression += '1/(';
    } else if (funcName === 'fact') {
      state.expression += '!';
    } else if (funcName === 'abs') {
      state.expression += 'abs(';
    } else if (funcName === 'sqrt') {
      state.expression += SYM.SQRT + '(';
    } else {
      const activeName = state.isSecondActive && ['sin', 'cos', 'tan'].includes(funcName)
        ? 'a' + funcName
        : funcName;
      state.expression += activeName + '(';
    }

    updateDisplays();
    updateLivePreview();
  }

  function negateCurrent() {
    if (!state.expression) {
      state.expression = '-';
      updateDisplays();
      return;
    }

    if (state.expression.startsWith('-(') && state.expression.endsWith(')')) {
      state.expression = state.expression.slice(2, -1);
    } else {
      state.expression = `-(${state.expression})`;
    }

    updateDisplays();
    updateLivePreview();
  }

  function calculateResult() {
    if (!state.expression) return;

    let openCount = 0;
    for (const c of state.expression) {
      if (c === '(') openCount++;
      else if (c === ')') openCount--;
    }
    while (openCount > 0) {
      state.expression += ')';
      openCount--;
    }
    updateDisplays();

    try {
      const initialExpr = state.expression;
      const res = safeEvaluate(state.expression, state.angleUnit);

      if (typeof res === 'number' && !isNaN(res)) {
        state.lastResult = res;
        state.isCalculated = true;
        const formatted = formatDisplayNumber(res);
        if (resultDisplay) resultDisplay.textContent = formatted;
        setStatus('DONE');
        // Add to Calculation History
        addHistory(initialExpr, formatted);
      } else {
        throw new Error('Calculation error');
      }
    } catch (err) {
      if (resultDisplay) resultDisplay.textContent = err.message || 'Error';
      setStatus('ERROR', true);
    }
  }

  // =========================================================================
  // KEYPAD CLICK DISPATCHER
  // =========================================================================
  function handleButtonClick(e) {
    const btn = e.target.closest('.calc-btn');
    if (!btn) return;

    const action = btn.getAttribute('data-action');
    const insert = btn.getAttribute('data-insert');
    const op = btn.getAttribute('data-op');
    const func = btn.getAttribute('data-func');

    if (action === 'clear') {
      clearAll();
    } else if (action === 'backspace') {
      backspace();
    } else if (action === 'calculate') {
      calculateResult();
    } else if (action === 'toggle-2nd') {
      toggleSecondFunction();
    } else if (action === 'toggle-angle') {
      toggleAngleUnit();
    } else if (action === 'negate') {
      negateCurrent();
    } else if (insert) {
      let text = insert;
      if (btn.getAttribute('data-alias') === 'pi') text = SYM.PI;
      insertString(text);
    } else if (op) {
      let text = op;
      if (btn.getAttribute('data-alias') === '/') text = SYM.DIV;
      if (btn.getAttribute('data-alias') === '*') text = SYM.MULT;
      if (btn.getAttribute('data-alias') === '-') text = SYM.SUB;
      insertOperator(text);
    } else if (func) {
      insertFunction(func);
    }
  }

  // =========================================================================
  // KEYBOARD INPUT SUPPORT
  // =========================================================================
  function handleKeyboard(e) {
    if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA' || e.ctrlKey || e.metaKey) {
      return;
    }

    const key = e.key;

    // If History drawer is open, Escape closes it
    if (historyDrawer && historyDrawer.classList.contains('open')) {
      if (key === 'Escape' || key === 'h' || key === 'H') {
        e.preventDefault();
        toggleHistoryDrawer(false);
        return;
      }
    }

    if (key >= '0' && key <= '9') {
      e.preventDefault();
      insertString(key);
      highlightKey(`[data-insert="${key}"]`);
    } else if (key === '.') {
      e.preventDefault();
      insertString('.');
      highlightKey('[data-insert="."]');
    } else if (key === '+') {
      e.preventDefault();
      insertOperator('+');
      highlightKey('[data-op="+"]');
    } else if (key === '-') {
      e.preventDefault();
      insertOperator(SYM.SUB);
      highlightKey('[data-op*="minus"], [data-alias="-"]');
    } else if (key === '*' || key === 'x' || key === 'X') {
      e.preventDefault();
      insertOperator(SYM.MULT);
      highlightKey('[data-op*="times"], [data-alias="*"]');
    } else if (key === '/') {
      e.preventDefault();
      insertOperator(SYM.DIV);
      highlightKey('[data-op*="divide"], [data-alias="/"]');
    } else if (key === '%') {
      e.preventDefault();
      insertOperator('%');
      highlightKey('[data-op="%"]');
    } else if (key === '^') {
      e.preventDefault();
      insertOperator('^');
      highlightKey('[data-op="^"]');
    } else if (key === '(' || key === ')') {
      e.preventDefault();
      insertString(key);
      highlightKey(`[data-insert="${key}"]`);
    } else if (key === 'Enter' || key === '=') {
      e.preventDefault();
      calculateResult();
      highlightKey('[data-action="calculate"]');
    } else if (key === 'Backspace') {
      e.preventDefault();
      backspace();
      highlightKey('[data-action="backspace"]');
    } else if (key === 'Escape' || key === 'c' || key === 'C') {
      e.preventDefault();
      clearAll();
      highlightKey('[data-action="clear"]');
    } else if (key === '!') {
      e.preventDefault();
      insertFunction('fact');
      highlightKey('[data-func="fact"]');
    } else if (key === 'p' || key === 'P') {
      e.preventDefault();
      insertString(SYM.PI);
      highlightKey('[data-alias="pi"]');
    } else if (key === 'e' || key === 'E') {
      e.preventDefault();
      insertString('e');
      highlightKey('[data-insert="e"]');
    } else if (key === 's' || key === 'S') {
      e.preventDefault();
      insertFunction('sin');
      highlightKey('[data-func="sin"]');
    } else if (key === 'l' || key === 'L') {
      e.preventDefault();
      insertFunction('log');
      highlightKey('[data-func="log"]');
    } else if (key === 'r' || key === 'R') {
      e.preventDefault();
      insertFunction('sqrt');
      highlightKey('[data-func="sqrt"]');
    } else if (key === 'h' || key === 'H') {
      e.preventDefault();
      toggleHistoryDrawer();
    }
  }

  function highlightKey(selector) {
    try {
      const btn = document.querySelector(selector);
      if (btn) {
        btn.classList.add('active');
        setTimeout(() => btn.classList.remove('active'), 150);
      }
    } catch {}
  }

  // =========================================================================
  // MOBILE TABS VIEW CONTROLLER
  // =========================================================================
  function initMobileTabs() {
    tabButtons.forEach(btn => {
      btn.addEventListener('click', () => {
        tabButtons.forEach(b => b.classList.remove('active'));
        btn.classList.add('active');

        const view = btn.getAttribute('data-view');
        if (keypadLayout) {
          keypadLayout.setAttribute('data-view', view);
        }
      });
    });
  }

  // Expose methods for automated testing & verification
  window.__safeEvaluate = safeEvaluate;
  window.__state = state;
  window.__addHistory = addHistory;
  window.__clearHistory = clearHistory;

  // =========================================================================
  // INITIALIZATION
  // =========================================================================
  function init() {
    initTheme();
    initHistory();
    initMobileTabs();

    if (angleUnitBtn) {
      angleUnitBtn.addEventListener('click', toggleAngleUnit);
    }

    if (keypadLayout) {
      keypadLayout.addEventListener('click', handleButtonClick);
    }

    window.addEventListener('keydown', handleKeyboard);

    clearAll();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }

})();
